package app.monstera.sample.runtime

/** Replays a recorded input trace without a shell (contract section 5) and reports checkpoints. */

class TickInput(val tick: Int, val events: List<InputEvent>)

data class Checkpoint(val tick: Int, val hash: ULong, val observe: List<Long>)

fun replay(config: RuntimeConfig, seed: ULong, ticks: Int, inputs: List<TickInput>, checkpointTicks: List<Int>): List<Checkpoint> {
    val world = World(config, seed)
    val byTick = HashMap<Int, MutableList<InputEvent>>()
    for (item in inputs) byTick.getOrPut(item.tick) { mutableListOf() }.addAll(item.events)
    val wanted = checkpointTicks.toSet()
    val out = ArrayList<Checkpoint>()
    if (0 in wanted) out.add(Checkpoint(0, world.stateHash(), world.observe()))
    for (i in 0 until ticks) {
        world.step(byTick[i] ?: emptyList())
        if ((i + 1) in wanted) out.add(Checkpoint(i + 1, world.stateHash(), world.observe()))
    }
    return out
}
